style.css:
@-moz-document domain("roblox.com") {
/* Background customization */
    body {
        background: url("https://preview.redd.it/qeekbd60jpb81.png?width=1080&crop=smart&auto=webp&s=25407676bc2c3b42f2dfe257f74d00ca1ae43506") no-repeat center center fixed; /* Custom image */
        background-size: cover; /* Make the image cover the screen */
        color: #ffffff !important; /* White text for better readability */
    }

    /* Header customization */
    .navbar {
        background-color: rgba(0, 0, 51, 0.8) !important; /* Semi-transparent navy blue (#000033) */
        border-bottom: 2px solid #0000ff !important; /* Bright blue border for the header */
    }

    /* Button customization */
    .btn-primary {
        background-color: #0000ff !important; /* Bright blue buttons */
        border: 1px solid #000000 !important; /* Black border */
        color: #ffffff !important; /* White text on buttons */
    }

    /* Link customization */
    a {
        color: #1e90ff !important; /* Dodger blue for links */
    }

    a:hover {
        color: #add8e6 !important; /* Light blue for hovered links */
    }

    /* Footer customization */
    .footer {
        background-color: rgba(0, 0, 0, 0.8) !important; /* Semi-transparent black for the footer */
        color: #1e90ff !important; /* Dodger blue text in the footer */
    }

    /* Remove ads (optional) */
    .ad-banner,
    .ad-container,
    .ad-slot {
        display: none !important;
    }
}
